class Solution:

	def f(self, arr, i, k, dp):
		if i < 0:
			if k > 0:
				return 1
			else:
				return 0
		if dp[i][k] != -1:
			return dp[i][k]
		nt = self.f(arr, i - 1, k, dp)
		t = 0
		if arr[i] <= k:
			t = self.f(arr, i - 1, k // arr[i], dp)
		dp[i][k] = t + nt
		return dp[i][k]

	def numOfSubsets(self, arr, n, k):
		dp = [[-1] * (k + 1) for _ in range(n + 1)]
		return self.f(arr, n - 1, k, dp) - 1
